const out = [];
for (const item of $input.all()) { const t = item.json || {}; if (!t.activity_id) continue; const stats = t.stats || {}; const article = (t.content && t.content.article) ? t.content.article : {}; out.push({ json: { activity_id: t.activity_id, post_url: t.post_url || '', text: t.text || '', full_urn: t.full_urn || '', author: t.author || {}, totalReactions: stats.total_reactions || 0, comments: stats.comments || 0, reshares: stats.shares || 0, posted_at: (t.posted_at && t.posted_at.date) ? t.posted_at.date : null, hashtags: t.hashtags || [], content: t.content || {}, is_reshare: !!t.is_reshare, metadata: t.metadata || {}, search_input: t.search_input || {}, title: article.title || '', imageURL: article.thumbnail_url || '', source: 'keyword' } }); }
return out;

const ctx = $('Build Context').first().json;
const urn = ctx.linkedin_urn ? String(ctx.linkedin_urn) : '';
const company_urns = urn;
const urnMap = {};
if (urn) urnMap[urn] = ctx.name;
return [{ json: { company_urns, urnMap } }];

const urnMap = $('Build LinkedIn URN Queries').first().json.urnMap || {};
const out = [];
for (const item of $input.all()) {
  const t = item.json || {};
  if (!t.activity_id) continue;
  const stats = t.stats || {};
  const article = (t.content && t.content.article) ? t.content.article : {};
  const author = t.author || {};
  const cn = urnMap[String(author.profile_id || '')] || null;
  out.push({ json: { activity_id: t.activity_id, post_url: t.post_url || '', text: t.text || '', full_urn: t.full_urn || '', author: author, totalReactions: stats.total_reactions || 0, comments: stats.comments || 0, reshares: stats.shares || 0, posted_at: (t.posted_at && t.posted_at.date) ? t.posted_at.date : null, hashtags: t.hashtags || [], content: t.content || {}, is_reshare: !!t.is_reshare, metadata: t.metadata || {}, search_input: t.search_input || {}, title: article.title || '', imageURL: article.thumbnail_url || '', source: 'company_page', companyHint: cn } });
}
return out;

const items = $input.all().map(i => i.json);
const map = new Map();
for (const r of items) {
  const id = r.activity_id;
  if (!id) continue;
  const ex = map.get(id);
  if (!ex) { map.set(id, r); continue; }
  if (ex.source !== 'company_page' && r.source === 'company_page') map.set(id, r);
}
return Array.from(map.values()).map(j => ({ json: j }));

const ctx = $('Build Context').first().json;
const cn = ctx.name;
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  out.push({ json: { activity_id: r.activity_id, companyName: cn, sentiment: null, reasoning: 'company self-post (auto-accepted)' } });
}
return out;

const results = [];
function llmText(j){
  if (j && Array.isArray(j.output)) { for (const mm of j.output) { if (mm && Array.isArray(mm.content)) { for (const c of mm.content) { if (c && typeof c.text === 'string') return c.text; } } } }
  if (j && typeof j.text === 'string') return j.text;
  if (j && typeof j.content === 'string') return j.content;
  if (j && j.message && typeof j.message.content === 'string') return j.message.content;
  if (j && Array.isArray(j.choices) && j.choices[0]) { const ch = j.choices[0]; if (ch.message && (ch.message.content || ch.message.reasoning)) return ch.message.content || ch.message.reasoning; if (typeof ch.text === 'string') return ch.text; }
  return '';
}
for (const item of $input.all()) {
  let raw = String(llmText(item.json) || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!raw) continue;
  const a = raw.indexOf('['); const b = raw.lastIndexOf(']');
  const txt = (a !== -1 && b !== -1 && b > a) ? raw.slice(a, b + 1) : raw;
  let parsed; try { parsed = JSON.parse(txt); } catch (e) { continue; }
  const arr = Array.isArray(parsed) ? parsed : [parsed];
  for (const e of arr) results.push({ json: e });
}
return results;

const dd = $('Dedup LinkedIn by activity_id').all().map(i => i.json);
const byId = {};
for (const p of dd) byId[p.activity_id] = p;
const out = [];
for (const item of $input.all()) {
  const r = Object.assign({}, item.json);
  const src = byId[r.activity_id];
  if (src && src.source === 'company_page') {
    if (!r.companyName || r.companyName === 'NONE') r.companyName = src.companyHint || r.companyName;
  }
  out.push({ json: r });
}
return out;

const helpers = this.helpers;
const SRK = '<REDACTED_SUPABASE_JWT>';
const SB = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
// classifier cache (author_affiliation): employees only -> "competitor|profile_id"
const EMP = {};
try {
  const aff = await helpers.httpRequest({ method: 'GET', url: SB + '/author_affiliation?select=profile_id,competitor&verdict=eq.employee', headers: { apikey: SRK, Authorization: 'Bearer ' + SRK }, json: true });
  for (const a of (aff || [])) { if (a && a.profile_id && a.competitor) EMP[String(a.competitor).trim().toLowerCase() + '|' + String(a.profile_id)] = true; }
} catch (e) { /* table absent/unreachable -> fall back to URN+headline heuristic */ }

const ctx = $('Build Context').first().json; const cfg = ctx.config || {};
const ew = (cfg.engagementWeights && cfg.engagementWeights.LinkedIn) || { reaction:1, comment:3, reshare:10, image:1.5 };
const clamp = cfg.sentimentClamp || { min:0.5, max:1.3 };
const halfLife = (cfg.halfLifeDays && cfg.halfLifeDays.LinkedIn) || 14;
// TERNARY author model (2026-07-02): company (own page/URN) B1 M1 · employee (classifier/headline) B2 M1.2 · external B5 M2
const AB = cfg.authorBaseline || { company:1.0, employee:2.0, external:5.0 };   // additive presence floor
const AEM = cfg.authorEngMult || { company:1.0, employee:1.2, external:2.0 };   // engagement multiplier (external = new eyes)
const companies = ctx.companies || [];
const urnSet = new Set(companies.map(c => String(c.linkedin_urn||'')).filter(Boolean));
const posts = $('Dedup LinkedIn by activity_id').all().map(i=>i.json);
const results = [];
for (const item of $input.all()) {
  const r = item.json;
  const post = posts.find(p => p.activity_id === r.activity_id) || {};
  const reactions = Number(post.totalReactions||0);
  const comments = Number(post.comments||0);
  const reshares = Number(post.reshares||0);
  const hasImage = post.imageURL && String(post.imageURL).length > 0;
  let eng = ((ew.reaction!=null?ew.reaction:1)*reactions) + ((ew.comment!=null?ew.comment:3)*comments) + ((ew.reshare!=null?ew.reshare:10)*reshares);
  if (hasImage) eng += (ew.image!=null?ew.image:1.5);
  const reach = Math.pow(eng, 49/50); // near-linear reach
  // sentMult: company-page self-posts (no self-sentiment) and unscored sentiment -> neutral 1.0; else 0.5..1.3
  const sentMult = (post.source === 'company_page' || r.sentiment == null) ? 1.0 : (clamp.min + ((Math.max(-3,Math.min(3,Number(r.sentiment)))+3)/6)*(clamp.max-clamp.min));
  const author = post.author || {};
  const headline = String(author.headline||'').toLowerCase();
  const authorUrn = String(author.profile_id||'');
  const cn = String(r.companyName||'');
  let authorType;
  if (post.source === 'company_page') authorType = 'company';
  else if (authorUrn && urnSet.has(authorUrn)) authorType = 'company';
  else if (authorUrn && cn && cn !== 'NONE' && EMP[cn.toLowerCase() + '|' + authorUrn]) authorType = 'employee'; // classifier-confirmed employee
  else if (cn && cn !== 'NONE' && headline.indexOf(cn.toLowerCase()) !== -1) authorType = 'employee'; // headline names the company
  else authorType = 'external';
  const B = (authorType === 'company') ? (AB.company!=null?AB.company:1.0) : (authorType === 'employee') ? (AB.employee!=null?AB.employee:2.0) : (AB.external!=null?AB.external:5.0);
  const M = (authorType === 'company') ? (AEM.company!=null?AEM.company:1.0) : (authorType === 'employee') ? (AEM.employee!=null?AEM.employee:1.2) : (AEM.external!=null?AEM.external:2.0);
  let ageDays = 0; if (post.posted_at) { const d = new Date(post.posted_at); if (!isNaN(d)) ageDays = Math.max(0,(Date.now()-d.getTime())/86400000); }
  const timeDecay = ageDays <= 7 ? 1 : Math.pow(2, -ageDays/halfLife); // 7-day grace, matches Weekly Decay Refresh
  const post_weight = (B + reach * M) * sentMult * timeDecay;
  results.push({ json: { activity_id: r.activity_id, sentiment: r.sentiment, reasoning: r.reasoning, companyName: r.companyName, authorType: authorType, post_weight: parseFloat(post_weight.toFixed(6)) } });
}
return results;

// Weekly classify-new-authors: grow the author_affiliation cache with authors seen
// this run that aren't cached yet. Heuristic only (URN/headline); unknowns are
// cached as 'ambiguous' (treated as external for scoring) so a periodic profile-
// scrape pass resolves them. Scrape/LLM are intentionally NOT run in-flow (cost).
// Terminal branch off 'Write LinkedIn post_weight' — never blocks scoring.
const helpers = this.helpers;
const SRK = '<REDACTED_SUPABASE_JWT>';
const SB = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H = { apikey: SRK, Authorization: 'Bearer ' + SRK };
const now = new Date().toISOString();

const ctx = $('Build Context').first().json;
const companies = (ctx.companies || []);
const urnSet = new Set(companies.map(c => String(c.linkedin_urn||'')).filter(Boolean));

// existing cache keys (so we only classify NEW authors)
let existing = new Set();
try {
  const aff = await helpers.httpRequest({ method:'GET', url: SB + '/author_affiliation?select=key', headers: H, json: true });
  for (const a of (aff || [])) if (a && a.key) existing.add(String(a.key));
} catch (e) { return [{ json: { cached: 0, note: 'cache read failed: ' + (e.message || e) } }]; }

// attributed posts this run (companyName set) joined to their author object
const attributed = $('Compute LinkedIn post_weight').all().map(i=>i.json);
const byId = {}; for (const p of $('Dedup LinkedIn by activity_id').all().map(i=>i.json)) byId[p.activity_id] = p;

const rows = {}; // pid -> verdict row (dedupe within run)
for (const r of attributed) {
  const cn = String(r.companyName||'');
  if (!cn || cn === 'NONE') continue;
  const post = byId[r.activity_id] || {};
  const a = post.author || {};
  const pid = String(a.profile_id||'');
  if (!pid || urnSet.has(pid)) continue;          // no id, or the company page itself
  if (existing.has(pid) || rows[pid]) continue;    // already cached / already handled this run
  const head = String(a.headline||'').toLowerCase();
  const verdict = (head && head.indexOf(cn.toLowerCase()) !== -1) ? 'employee' : 'ambiguous';
  rows[pid] = { key: pid, name: a.name || null, profile_id: pid, competitor: cn, verdict: verdict, employer: (verdict === 'employee' ? cn : null), method: 'heuristic', checked_at: now };
}
const list = Object.values(rows);
if (!list.length) return [{ json: { cached: 0 } }];
const hh = Object.assign({}, H, { 'Content-Type':'application/json', 'Prefer':'resolution=merge-duplicates,return=minimal' });
try { await helpers.httpRequest({ method:'POST', url: SB + '/author_affiliation?on_conflict=key', headers: hh, body: list, json: true }); }
catch (e) { return [{ json: { cached: 0, error: (e.message || String(e)) } }]; }
return [{ json: { cached: list.length, employee: list.filter(r=>r.verdict==='employee').length, ambiguous: list.filter(r=>r.verdict==='ambiguous').length } }];

const co = ($('Build Context').first().json && $('Build Context').first().json.name) || 'unknown';
let linkedinWritten = 0; try { linkedinWritten = $('Write LinkedIn post_weight').all().length; } catch(e){}
return [{ json: { company: co, linkedinWritten: linkedinWritten, ok: true } }];
